/*
 * Receives device notifications (Web Push) and shows them (ADR-0081 §3).
 *
 * Loaded into the Service Worker generated by vite-plugin-pwa via `importScripts`
 * (`workbox.importScripts` in `vite.config.ts`). Only the receiving part lives in this file so
 * the generated output never needs hand edits.
 *
 * Payload has the shape sent by the server's `WebPushSender`: { id, title, body, url }.
 */
/* eslint-disable no-restricted-globals */
self.addEventListener('push', (event) => {
  let data = {}
  try {
    data = event.data ? event.data.json() : {}
  } catch {
    data = { title: event.data ? event.data.text() : '' }
  }
  const title = data.title || self.registration.scope
  event.waitUntil(
    Promise.all([
      self.registration.showNotification(title, {
        body: data.body || '',
        icon: '/pwa-192x192.png',
        badge: '/pwa-192x192.png',
        // Don't show the same notice twice (a redelivery replaces it).
        tag: data.id ? `notification-${data.id}` : undefined,
        data: { url: data.url || '/' },
      }),
      // Have open screens refetch the bell (`store/InboxContext.tsx`).
      self.clients.matchAll({ type: 'window' }).then((clients) => {
        clients.forEach((client) => client.postMessage({ type: 'notification-received' }))
      }),
    ]),
  )
})

self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const target = new URL(
    (event.notification.data && event.notification.data.url) || '/',
    self.location.origin,
  )
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clients) => {
      // For in-app destinations, reuse an open screen (don't add tabs).
      if (target.origin === self.location.origin) {
        const existing = clients.find((client) => new URL(client.url).origin === target.origin)
        if (existing) {
          // ⚠ navigate only works on screens controlled by the Service Worker. If it fails, open anew.
          return existing
            .focus()
            .then((client) => client.navigate(target.href))
            .catch(() => self.clients.openWindow(target.href))
        }
      }
      return self.clients.openWindow(target.href)
    }),
  )
})
